(async () => {
 const originalAdd = window.addEventListener, originalRemove = window.removeEventListener;
 const active = new Map();
 window.addEventListener = function(type, fn, options) { if (type.startsWith("practice-")) { if (!active.has(type)) active.set(type,new Set()); active.get(type).add(fn); } return originalAdd.call(this,type,fn,options); };
 window.removeEventListener = function(type, fn, options) { active.get(type)?.delete(fn); return originalRemove.call(this,type,fn,options); };
 const pause = () => new Promise(r=>setTimeout(r,25));
 const click = text => [...document.querySelectorAll("button")].find(b=>b.textContent === text)?.click();
 try {
 click("Show listener"); await pause();
 window.dispatchEvent(new Event("practice-alpha")); await pause();
 if (document.querySelector("[role=status]")?.textContent !== "Received: 1") return false;
 click("Switch channel"); await pause();
 window.dispatchEvent(new Event("practice-alpha")); await pause();
 if (document.querySelector("[role=status]")?.textContent !== "Received: 1") return false;
 window.dispatchEvent(new Event("practice-beta")); await pause();
 if (document.querySelector("[role=status]")?.textContent !== "Received: 2") return false;
 click("Hide listener"); await pause();
 return !document.querySelector("[role=status]") && [...active.values()].every(set=>set.size===0);
 } finally { for (const [type,listeners] of active) for (const fn of listeners) originalRemove.call(window,type,fn); window.addEventListener=originalAdd; window.removeEventListener=originalRemove; }
})()
